        createdByGuid = "Player-1-Alice",
        createdByName = "Alice-Garona",
        startedAt = 50,
        bankTabAtStart = 2,
        boundaryVersion = 1,
        boundaryKind = "new-goal",
        contextStatus = "unavailable",
        contextRecordCount = 0,
    })
